#!/usr/bin/env python3
"""
validate-hebrew-punctuation.py

Checks logical (not visual) balance of parentheses, brackets, and quotation
marks in Hebrew/mixed-script markdown articles, and flags cases where bidi
control marks are plausibly missing around embedded Latin/digit runs inside
RTL paragraphs.

Rationale: the Unicode BiDi algorithm and Word's w:bidi both operate on the
LOGICAL (memory) order of a paragraph, not the visual order. A "(" and ")"
that are unbalanced in the logical text will render broken regardless of
script direction, so this validator counts pairs in logical order exactly as
it would for any other language -- it does not try to reason about visual
left/right position.

Also implements one acronym-aware heuristic for Hebrew straight-quote (")
usage: a `"` with a Hebrew letter immediately before AND after it (no
whitespace) is a rashei-tevot / acronym marker (e.g. tanach, malachim-alef)
rather than a quotation delimiter, and is excluded from quotation-pair
counting so it doesn't produce false positives.

Usage:
    python3 scripts/validate-hebrew-punctuation.py <file-or-directory> [...]

Exit code: 0 if no violations found, 1 if any violations found.
Dependency-free (Python 3 stdlib only).
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

HEB = r"א-ת"  # Hebrew alef-tav block
HEB_ANY = r"֐-׿יִ-ﭏ"  # Hebrew block + presentation forms

# Bidi control characters (their absence around embedded LTR/digit runs in an
# RTL paragraph is a plausible -- not certain -- sign of a stripped-marks bug).
BIDI_MARKS = (
    "‎‏"  # LRM, RLM
    "‪‫‬‭‮"  # LRE, RLE, PDF, LRO, RLO
    "⁦⁧⁨⁩"  # LRI, RLI, FSI, PDI
)

PAREN_PAIRS = [("(", ")"), ("[", "]")]

ACRONYM_QUOTE_RE = re.compile(rf"(?<=[{HEB}])\"(?=[{HEB}])")

# A run of 2+ Latin letters or digits (a "foreign" run) sitting inside a
# Hebrew-majority paragraph, immediately abutting a Hebrew quotation mark
# (gershayim/geresh) with NO space and no bidi isolate/mark in between.
# Deliberately narrow: plain "(1991)" style digit-in-parens is excluded
# because paired brackets already mirror correctly under the bidi algorithm
# without marks -- the genuinely risky case is a Latin/digit run directly
# touching a Hebrew-specific punctuation glyph (״ / ׳), which is where the
# script-boundary is ambiguous without an explicit mark.
FOREIGN_RUN_ADJACENT_HEB_PUNCT_RE = re.compile(r"([A-Za-z0-9]{2,})([״׳])(?!\d)")

MD_HEADING_RE = re.compile(r"^#{1,6}\s")


def split_paragraphs(text: str) -> list[tuple[int, str]]:
    """Split markdown text into (start_line_number, paragraph_text) blocks."""
    lines = text.split("\n")
    paragraphs: list[tuple[int, str]] = []
    buf: list[str] = []
    start_line = 1
    for i, line in enumerate(lines, start=1):
        if line.strip() == "":
            if buf:
                paragraphs.append((start_line, "\n".join(buf)))
                buf = []
            start_line = i + 1
            continue
        if not buf:
            start_line = i
        buf.append(line)
    if buf:
        paragraphs.append((start_line, "\n".join(buf)))
    return paragraphs


def is_hebrew_majority(text: str) -> bool:
    heb = len(re.findall(rf"[{HEB_ANY}]", text))
    lat = len(re.findall(r"[A-Za-z]", text))
    return heb > 0 and heb >= lat


def context_snippet(text: str, idx: int, width: int = 50) -> str:
    start = max(0, idx - width)
    end = min(len(text), idx + width)
    snippet = text[start:end].replace("\n", " ↵ ")
    return snippet


def check_paragraph(path: Path, start_line: int, para: str) -> list[str]:
    violations: list[str] = []

    for open_ch, close_ch in PAREN_PAIRS:
        opens = para.count(open_ch)
        closes = para.count(close_ch)
        if opens != closes:
            idx = para.find(open_ch) if opens > closes else para.find(close_ch)
            snippet = context_snippet(para, idx if idx >= 0 else 0)
            violations.append(
                f"{path}:{start_line}: UNBALANCED_BRACKET "
                f"'{open_ch}'={opens} vs '{close_ch}'={closes} :: ...{snippet}..."
            )

    # Quote-pair check: drop acronym-style quotes first, then require an even
    # count of the remainder.
    stripped = ACRONYM_QUOTE_RE.sub("", para)
    dq_count = stripped.count('"')
    if dq_count % 2 == 1:
        idx = para.rfind('"')
        snippet = context_snippet(para, idx if idx >= 0 else 0)
        violations.append(
            f"{path}:{start_line}: UNBALANCED_QUOTE "
            f"straight-double-quote count (excl. acronym markers) is odd "
            f"({dq_count}) :: ...{snippet}..."
        )

    # Gershayim balance (paired quotation use of ״ is much rarer than
    # acronym use, but a lone gershayim adjacent to a straight quote is a
    # strong signal of a mixed-quote-character defect, e.g. ״text" ).
    mixed = re.search(r'״[^״"]{0,200}"', para) or re.search(r'"[^״"]{0,200}״', para)
    if mixed:
        idx = mixed.start()
        snippet = context_snippet(para, idx)
        violations.append(
            f"{path}:{start_line}: MIXED_QUOTE_CHARACTER "
            f'gershayim (״) paired with a straight quote (") :: ...{snippet}...'
        )

    # Bidi-mark sanity heuristic: only applies to Hebrew-majority paragraphs
    # that contain no bidi control marks at all, and only flags the clearest
    # case -- a Latin/digit run directly abutting Hebrew punctuation with no
    # space and no isolate/mark between them.
    if is_hebrew_majority(para) and not any(ch in para for ch in BIDI_MARKS):
        for m in FOREIGN_RUN_ADJACENT_HEB_PUNCT_RE.finditer(para):
            snippet = context_snippet(para, m.start())
            violations.append(
                f"{path}:{start_line}: BIDI_MARK_LIKELY_MISSING "
                f"Latin/digit run directly abuts Hebrew-context punctuation "
                f"with no space and no bidi mark :: ...{snippet}..."
            )

    return violations


def check_file(path: Path) -> list[str]:
    try:
        text = path.read_text(encoding="utf-8", errors="strict")
    except UnicodeDecodeError as e:
        return [f"{path}: SKIPPED (not valid UTF-8: {e})"]

    violations: list[str] = []
    for start_line, para in split_paragraphs(text):
        if MD_HEADING_RE.match(para.strip()):
            # headings are short and rarely a real risk; still check them,
            # just don't special-case them out -- fall through.
            pass
        violations.extend(check_paragraph(path, start_line, para))
    return violations


def collect_files(paths: list[str]) -> list[Path]:
    files: list[Path] = []
    for p in paths:
        pp = Path(p)
        if pp.is_dir():
            files.extend(sorted(pp.rglob("*.md")))
        elif pp.is_file():
            files.append(pp)
        else:
            print(f"WARNING: path not found: {p}", file=sys.stderr)
    return files


def main(argv: list[str]) -> int:
    if not argv:
        print(__doc__)
        return 1

    files = collect_files(argv)
    if not files:
        print("No .md files found to check.")
        return 0

    total_violations = 0
    for f in files:
        violations = check_file(f)
        for v in violations:
            print(v)
        total_violations += len(violations)

    print()
    print(f"Checked {len(files)} file(s); {total_violations} violation(s) found.")
    return 1 if total_violations else 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
